 3	    static int cutRod(int[] price) {
 4	        validatePriceTable(price);
 5	
 6	        int rodLength = price.length - 1;
 7	        int[] bestRevenueByLength = new int[rodLength + 1];
 8	
 9	        for (int currentLength = 1; currentLength <= rodLength; currentLength++) {
10	            bestRevenueByLength[currentLength] =
11	                    computeBestRevenue(price, bestRevenueByLength, currentLength);
12	        }
13	
14	        return bestRevenueByLength[rodLength];
15	    }
