17	    private static void validatePriceTable(int[] price) {
18	        if (price == null || price.length == 0) {
19	            throw new IllegalArgumentException("Price table must contain a sentinel at index 0.");
20	        }
21	    }
22	
23	    private static int computeBestRevenue(int[] price, int[] bestRevenueByLength, int targetLength) {
24	        int bestRevenue = 0;
25	
26	        for (int firstCutLength = 1; firstCutLength <= targetLength; firstCutLength++) {
27	            bestRevenue = Math.max(
28	                    bestRevenue,
29	                    price[firstCutLength] + bestRevenueByLength[targetLength - firstCutLength]
30	            );
31	        }
32	
33	        return bestRevenue;
34	    }
